import type { LocationQueryValue } from 'vue-router';
import { SUBCONTRACTOR_COMPANY_UNASSIGNED_VALUE } from '~/constants/subcontractor-companies/filter';

export type SubcontractorCompanyFilter = {
  subcontractor_company_ids: string[] | undefined;
  include_unassigned: true | undefined;
};

export function parseSubcontractorCompanyFilter(
  query: LocationQueryValue | LocationQueryValue[] | undefined
): SubcontractorCompanyFilter {
  const arr = !query ? [] : Array.isArray(query) ? query : [query];
  const strings = arr.filter((v): v is string => typeof v === 'string');
  const hasUnassigned = strings.includes(SUBCONTRACTOR_COMPANY_UNASSIGNED_VALUE);
  const ids = strings.filter((v) => v !== SUBCONTRACTOR_COMPANY_UNASSIGNED_VALUE);
  return {
    subcontractor_company_ids: ids.length > 0 ? ids : undefined,
    include_unassigned: hasUnassigned ? true : undefined,
  };
}
