<template>
  <AppMultiComboboxQuery
    v-if="isMultiple"
    :value="mergedValue"
    :groups="selectGroups"
    :property-name="propertyName"
    :null-is-all="nullIsAll"
    :loading="isLoading"
    :error="error"
    :placeholder="placeholder"
    :input-placeholder="inputPlaceholder"
    :items-plural-name="itemsPluralName"
    :empty-text="emptyText"
    :icon="icon || FilterIcon"
    :label="label"
    :is-first-page-only="isFirstPageOnly"
    @change="onChange"
  />
  <AppComboboxQuery
    v-else
    :value="mergedValue ? mergedValue[0] : null"
    :groups="selectGroups"
    :property-name="propertyName"
    :null-is-all="nullIsAll"
    :loading="isLoading"
    :error="error"
    :placeholder="placeholder"
    :input-placeholder="inputPlaceholder"
    :items-plural-name="itemsPluralName"
    :empty-text="emptyText"
    :icon="icon || FilterIcon"
    :label="label"
    :is-first-page-only="isFirstPageOnly"
    @change="onChange"
  />
</template>

<script setup lang="ts">
import { getSelectorSubcontractorCompanyList, type GetSelectorSubcontractorCompanyListResponse } from '~/client';
import { FilterIcon } from 'lucide-vue-next';
import {
  SUBCONTRACTOR_COMPANY_UNASSIGNED_VALUE,
  SUBCONTRACTOR_COMPANY_UNASSIGNED_LABEL,
} from '~/constants/subcontractor-companies/filter';
import { mergeSubcontractorCompanyFilter } from '~/utils/mergeSubcontractorCompanyFilter';
import type { FunctionalComponent } from 'vue';

const props = withDefaults(
  defineProps<{
    subcontractorCompanyIds: string[] | null;
    includeUnassigned: boolean | null;
    propertyName: string;
    projectId?: string | null;

    placeholder: string;
    inputPlaceholder: string;
    emptyText: string;
    nullIsAll: boolean;
    itemsPluralName: string;
    icon?: FunctionalComponent;
    label?: string;
    isMultiple?: boolean;
    isFirstPageOnly?: boolean;
  }>(),
  {
    icon: undefined,
    label: undefined,
    projectId: null,
    isMultiple: true,
    isFirstPageOnly: true,
  }
);

const emit = defineEmits(['change']);

const { data, isLoading, error } = useQuery({
  key: () => ['selector-subcontractor-companies-list', props.projectId] as const,
  query: (): Promise<GetSelectorSubcontractorCompanyListResponse> =>
    getSelectorSubcontractorCompanyList({
      composable: '$fetch',
      query: { project_id: props.projectId ?? undefined },
    }),
});

const selectGroups = computed<SelectItemGroup[]>(() => [
  {
    items: [
      {
        name: SUBCONTRACTOR_COMPANY_UNASSIGNED_LABEL,
        value: SUBCONTRACTOR_COMPANY_UNASSIGNED_VALUE,
        emphasized: true,
        iconSrc: '/icon.svg',
      },
    ],
  },
  {
    label: 'Subcontractor Companies',
    items: data.value?.items.map((c) => ({ name: c.name, value: c.id, iconSrc: c.logo_url ?? undefined })) ?? [],
  },
]);

const mergedValue = computed<string[] | null>(() =>
  mergeSubcontractorCompanyFilter(props.subcontractorCompanyIds, props.includeUnassigned)
);

function onChange(value: string | string[] | null) {
  emit('change', value);
}
</script>
