import { SUBCONTRACTOR_COMPANY_UNASSIGNED_VALUE } from '~/constants/subcontractor-companies/filter';

export function mergeSubcontractorCompanyFilter(
  subcontractorCompanyIds: string[] | null,
  includeUnassigned: boolean | null
): string[] | null {
  const ids = subcontractorCompanyIds ?? [];
  const merged = includeUnassigned ? [SUBCONTRACTOR_COMPANY_UNASSIGNED_VALUE, ...ids] : [...ids];
  return merged.length > 0 ? merged : null;
}
